import { readFileSync } from 'node:fs';
import { createMDX } from 'fumadocs-mdx/next';
import { initOpenNextCloudflareForDev } from '@opennextjs/cloudflare';

initOpenNextCloudflareForDev();

const withMDX = createMDX();

// Old V3 reference URLs -> new ones, generated by `npm run api:build` whenever
// an operation's page URL changes (scripts/api/lib/redirects.mjs). Each also
// covers the `.md` variant that proxy.ts serves to LLM clients.
const v3Redirects = JSON.parse(readFileSync(new URL('./redirects.v3.json', import.meta.url), 'utf-8'));

/** @type {import('next').NextConfig} */
const config = {
  reactStrictMode: true,
  async redirects() {
    return v3Redirects.flatMap(({ source, destination }) => [
      { source, destination, permanent: true },
      { source: `${source}.md`, destination: `${destination}.md`, permanent: true },
    ]);
  },
};

export default withMDX(config);
